"""Main-site selection guides and reproducible patches to existing mod pages."""
from pathlib import Path
from html import escape
import json
import re

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://megabonk.org'
AD = '<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'
GA = '<script async src="https://www.googletagmanager.com/gtag/js?id=G-V5X87M8JFL"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag(\'js\',new Date());gtag(\'config\',\'G-V5X87M8JFL\');</script>'


def ext(url, label):
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'


def ref(n):
    return f'<sup><a href="#source-{n}" aria-label="Source {n}">[{n}]</a></sup>'


def table(head, rows):
    return '<div class="table-wrap" role="region" aria-label="Comparison table; scroll sideways on small screens" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'


def shell(path, title, desc, h1, answer, parts, sources=(), related=(), trust=False):
    nav = '<a href="/guides/">Guides</a><a href="/guides/builds/">Builds</a><a href="/database/">Database</a><a href="/mods/">Mods</a>'
    body = ''.join(f'<section id="{i}"><h2>{h}</h2>{t}</section>' for i,h,t in parts)
    if sources:
        body += '<section class="sources" id="sources"><h2>Sources and limits</h2><ol>'+''.join(f'<li id="source-{i}">{ext(u,l)} — {d}</li>' for i,(u,l,d) in enumerate(sources,1))+'</ol><p><a href="#guide">Back to guide ↑</a></p></section>'
    if related:
        body += '<section id="related"><h2>Related guides</h2><ul>'+''.join(f'<li><a href="{u}">{l}</a></li>' for u,l in related)+'</ul></section>'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{BASE+path}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{BASE+path}"><meta property="og:type" content="article"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/megabonk-guide.css">{'' if trust else AD+GA}</head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="nav"><a class="logo" href="/">Megabonk<span>.org</span></a><nav class="main-desktop" aria-label="Main navigation" style="display:flex;gap:1.2rem">{nav}</nav><details class="main-mobile"><summary>Menu</summary><nav aria-label="Mobile navigation">{nav}</nav></details></div></header><main id="main" class="guide-body"><nav class="crumb" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="{'/mods/' if path.startswith('/mods/') else '/guides/'}">{'Mods' if path.startswith('/mods/') else 'Guides'}</a></nav><header id="guide"><p class="eyebrow">Independent player guide · October 28, 2026</p><h1>{h1}</h1><p class="lead">{answer}</p><p>By Megabonk.org · Source-based decisions; limits below.</p></header><nav class="jump" aria-label="On this page">{''.join(f'<a href="#{i}">{h}</a>' for i,h,_ in parts)}</nav>{body}</main><footer class="footer"><p>Megabonk.org is an independent player resource, not the developer or publisher of the games or mods covered.</p><nav aria-label="Site information"><a href="/about/">About</a> · <a href="/contact/">Contact</a> · <a href="/privacy-policy">Privacy</a></nav></footer></body></html>'''


def write(path, html):
    f = ROOT / path.strip('/') / 'index.html'
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_text(html, encoding='utf-8')


def build():
    together = 'https://thunderstore.io/c/megabonk/p/DShad/MegabonkTogether/'
    friends = 'https://thunderstore.io/c/megabonk/p/BonkWithFriends/BonkWithFriends/'
    reddit = 'https://www.reddit.com/r/MegabonkOfficial/comments/1uov3ve/megabonk_together_vs_bonk_with_friends_which_one/'
    sources = [(together, 'Thunderstore — DShad’s MegabonkTogether', 'Version 5.1.0; author features and limitations, checked October 28. A listing is not a current-patch compatibility test.'),
               (friends, 'Thunderstore — BonkWithFriends', 'Version 0.5.3; author feature claims, checked October 28. No multiplayer run or security audit performed here.'),
               (together+'required', 'Thunderstore — Together dependencies', 'Original live dependency page: BepInExPack IL2CPP 6.0.738, October 28.'),
               (friends+'required', 'Thunderstore — BonkWithFriends dependencies', 'Original live dependency page: BepInExPack IL2CPP 6.0.755, October 28. Search snapshots can retain older package versions.'),
               (reddit, 'Reddit r/MegabonkOfficial — Rudani’s comparison question', 'Read October 28. OlXondof and Funnypilz offer conflicting older experiences; neither establishes current 5.1.0-versus-0.5.3 stability.')]
    parts = [
        ('choose', 'Choose by the session you want', table(['Your priority', 'Project to inspect first', 'Why / remaining limit'], [('Private room codes or a random queue', 'MegabonkTogether', 'Advertised up to six players and direct P2P with relay fallback; not a guarantee every mechanic syncs.'), ('Steam friend invites and drop-in/drop-out', 'BonkWithFriends', 'Steamworks-oriented session flow; author advertises P2P without port forwarding.'), ('A proven stable full clear on your current patch', 'Neither established by this guide', 'Run the same small compatibility test with your actual group; do not choose by update date alone.'), ('Steam Deck / Proton', 'Inspect Together’s experimental documentation first', 'Experimental support is not a verified compatibility claim for your device or the other project.')])+f'<p>These are feature-based recommendations from the two authors, not head-to-head benchmark results.{ref(1)}{ref(2)}</p>'),
        ('compare', 'Compare the advertised behavior', table(['Question', 'MegabonkTogether 5.1.0', 'BonkWithFriends 0.5.3'], [('How do friends connect?', 'Private code or random queue; P2P with relay fallback.', 'Steam invite / join from friends; drop-in/drop-out P2P.'), ('Player count', 'Author advertises up to six.', 'This comparison does not establish a current maximum; check the live lobby rather than borrowing Together’s six.'), ('What is synchronized?', 'Author lists most weapons, projectiles, monsters, chests, shrines, portals and challenges, with explicit imperfect cases.', 'Author lists world generation, interactables, weapons, XP/level-ups and enemy physics.'), ('Death and communication', 'Death-camera/revival features in author documentation.', 'Spectator/revive and Enter-key in-game chat advertised.'), ('Declared loader', 'BepInExPack IL2CPP 6.0.738.', 'BepInExPack IL2CPP 6.0.755.'), ('Other gameplay mods', 'Author warns non-cosmetic combinations probably will not work reliably.', 'No universal compatibility promise established here.')])+f'<p>Dependencies are version-specific. Matching the multiplayer DLL while mixing different loader versions is not a matched profile.{ref(1)}{ref(2)}{ref(3)}{ref(4)}</p>'),
        ('reports', 'What the stability reports actually establish', f'<p>Rudani asks which project is more stable and notes conflicting recommendations. OlXondof says Together was better when they tried both months earlier. Funnypilz prefers BonkWithFriends in their more recent attempt but reports serious problems in both and says neither reached the end screen.</p><p>These are two respondents in one historical thread, with no controlled matching patch, package, hardware or full-clear sample. They establish uncertainty and a real comparison need; they do not establish today’s winner. More recent publication or a larger download counter cannot resolve that conflict.{ref(5)}</p>'),
        ('test', 'Use one short test before choosing the group’s profile', '<ol><li>Close the game and preserve a dated copy of the whole save folder before experimenting.</li><li>Create separate manager profiles for the two projects. Use one multiplayer project and its declared dependencies in each; avoid adding gameplay mods initially.</li><li>Have every participant record the game build, package, loader, other enabled mods and platform. Compare those exact values.</li><li>Test the intended join route, movement, enemies, XP, a reward, a death/revive and a portal. Stop if different players see different state.</li><li>Repeat the same route with the other project only if a comparison is still useful. Keep the profiles and backups separate.</li><li>Choose the route that meets your actual group’s needs and passed those checks. A short pass still does not establish a completed-run or long-session guarantee.</li></ol><p>This is our comparison method, not a report that we ran it. The installation guide retains the full manager, hosting and recovery steps.</p>'),
        ('download', 'Open the author’s exact package', f'<p>Use {ext(together, "Thunderstore — DShad/MegabonkTogether")} or {ext(friends, "Thunderstore — BonkWithFriends/BonkWithFriends")}. Check the package namespace, version and declared dependencies before using the manager install action. Do not combine both netcode projects in one profile.</p><p>We have not audited the binaries or certified an external download as safe. Preserve the source identity and backups; avoid presenting “newer” or “works for one commenter” as a security conclusion.</p>')]
    path = '/mods/megabonk-together-vs-bonk-with-friends/'
    write(path, shell(path, 'MegabonkTogether vs BonkWithFriends: Which Mod?', 'Compare MegabonkTogether and BonkWithFriends by rooms, Steam invites, dependencies and reported limits, then choose a profile for your group.', 'MegabonkTogether vs BonkWithFriends', f'Inspect MegabonkTogether for room-code/random-queue play and its advertised six-player support; inspect BonkWithFriends for Steam-invite, drop-in/drop-out play. Neither is proven the more stable current build here. Choose one project, match the whole group’s profile and test the mechanics you need.{ref(1)}{ref(2)}', parts, sources, [('/mods/multiplayer/', 'Install, host and troubleshoot co-op'), ('/guides/save-recovery', 'Preserve and recover Megabonk saves'), ('/faq/is-megabonk-multiplayer', 'Separate official support from mods')]))

    pb = 'https://pokebonk.com/?lang=en'
    ps = 'https://github.com/JPTER78/pokesurvivor'
    parts = [
        ('identify', 'Identify the game from what you saw', table(['What you remember', 'Candidate / next check', 'Why'], [('A 3D Pokémon arena and a browser entry', 'PokeBonk by Charcher at pokebonk.com.', 'The author describes a 3D horde-survival browser fan game.'), ('A 2D sprite-based Pokémon bullet-heaven', 'PokéSurvivor by JPTER78, linked by its original repository.', 'The repository identifies a different project, not a mode of PokeBonk.'), ('Megabonk characters, weapons and Tomes on Steam', 'The original Megabonk.', 'This is not a Pokémon skin or account for either browser project.')])+f'<p>A search phrase or video caption can refer to more than one project. Check the visible interface and author-linked host before using a guide.{ref(1)}{ref(2)}{ref(3)}</p>'),
        ('choose', 'Choose the part of Megabonk you want to keep', table(['Preference', 'Start here', 'Trade-off to keep visible'], [('3D space, camera movement and a Pokémon-themed survivor loop', 'PokeBonk', 'Your Megabonk builds and save do not transfer; learn its own kit and League systems.'), ('Pokémon sprite presentation and a separate bullet-heaven system', 'PokéSurvivor', 'Use its own builds, controls, progression and save guidance; a similar name is not shared rules.'), ('Megabonk itself with the existing weapon/Tome progression', 'Megabonk', 'It remains a separate Steam product; neither browser guide is its installation route.'), ('Play with a specific friend group', 'Check that exact project’s current co-op guide.', 'A Megabonk multiplayer mod, a PokeBonk room and PokéSurvivor co-op are different systems.')])+'<p>These are format and task recommendations. We did not benchmark all games, compare their full content or rank them by quality.</p>'),
        ('boundaries', 'Keep access, saves and versions separate', f'<p>PokeBonk’s original legal notice describes a browser-only fan project. An APK or another domain with the same title is not made official by its spelling. The author’s current entry and legal links are the identity reference.{ref(1)}{ref(4)}</p><p>Our PokeBonk and PokéSurvivor Play pages use disclosed third-party sources. Their accounts, versions and progress are separate from the original projects. For a first visit, identify your intended host; for an existing save, stay with its exact host and account before trying another game.</p><p>Both original projects describe themselves as unofficial fan work. They are not official Pokémon releases. “Games like” here compares a player task and format, not ownership or endorsement.</p>'),
        ('next', 'Take the matching next step', '<ul><li><a href="/pokebonk/beginners-guide/">PokeBonk: first run, keys and Guest session</a></li><li><a href="/poke-survivor/beginners-guide/">PokéSurvivor: its own first-run and partner decisions</a></li><li><a href="/guides/megabonk-beginners-guide">Megabonk: Steam-game beginner guide</a></li><li><a href="/mods/megabonk-together-vs-bonk-with-friends/">Already chose Megabonk? Compare its co-op mods</a></li></ul><p>We keep this selection focused on the two verified Pokémon survivor projects rather than padding it with unrelated turn-based games. New alternatives need their own author, access and gameplay verification.</p>')]
    path = '/guides/pokemon-games-like-megabonk/'
    write(path, shell(path, 'Pokemon Games Like Megabonk: Find the Right Game', 'Find the Pokemon game that resembles Megabonk. Compare PokeBonk and PokeSurvivor by 3D or 2D play, original entry, progression and separate saves.', 'Which Pokémon game plays like Megabonk?', f'If you mean a Pokémon-themed 3D survivor in a browser, check PokeBonk first. If you saw a 2D Pokémon bullet-heaven, check PokéSurvivor. They are separate fan projects, and neither is a Megabonk mod. Choose by the interface and systems you want, then use that project’s own entry and guide.{ref(1)}{ref(2)}', parts, [(pb,'pokebonk.com — Charcher’s original entry','Original 3D browser-game description, October 28.'), (ps,'GitHub — JPTER78/pokesurvivor','Original author repository, project identity and public entry, October 28.'), ('https://store.steampowered.com/app/3405340/Megabonk/','Steam — Megabonk by vedinad','Separate Steam product and horde-survival description; checked October 28.'), ('https://pokebonk.com/legal','pokebonk.com — legal notice','Author’s browser-only and unofficial-project statements; not a third-party security audit.')], [('/pokebonk/megabonk-vs-pokebonk/', 'Compare PokeBonk with the Steam game'), ('/poke-survivor/', 'Find the PokéSurvivor task index')]))

    # The original main site had no usable general About/Contact. These two
    # pages describe the actual multi-game publisher and add no ad/GA scripts.
    for path,title,desc,answer,parts in [
        ('/about/', 'About Megabonk.org: Independent Player Guides', 'Learn who maintains Megabonk.org, how sources and game editions are checked, and what source-based guides can and cannot establish.', 'Megabonk.org is an independent guide website maintained by its publisher. It covers Megabonk and selected related survivor games; it is not operated by the game or mod developers.', [('method','How we check guides','<p>We read original project pages, public game definitions, release notes and identified community reports. We distinguish listed behavior from our recommendations and from actual playtests. A menu or code inspection is not a full clear, a device benchmark or proof of account recovery. Pages state versions, dates and material limits.</p>'),('ownership','Names, artwork and corrections','<p>Game names and assets belong to their respective owners. Megabonk.org is not affiliated with vedinad, Charcher, JPTER78, Nintendo, The Pokémon Company, Creatures or GAME FREAK. Mod authors operate their own projects. Use our contact page to report an incorrect fact, broken link or rights concern.</p>')]),
        ('/contact/', 'Contact Megabonk.org: Corrections and Site Feedback', 'Contact the independent publisher of Megabonk.org about guide corrections, broken links or rights concerns, and distinguish game account support.', 'For website corrections, broken links or rights concerns, email the publisher at qsyhxw@gmail.com. This website cannot access or recover game accounts.', [('email','Send useful context','<p><a href="mailto:qsyhxw@gmail.com?subject=%5BMegabonk.org%5D%20Website%20feedback">Email qsyhxw@gmail.com</a> with the page URL, disputed passage, relevant game/version and a public source if available. Do not send game passwords, private save tokens or payment details. We do not promise a response deadline.</p>'),('support','Game and mod support','<p>For account, game server or mod problems, follow the support route linked by that original project. We do not operate their servers or approve third-party downloads. Email is handled through Gmail; our privacy notice explains the site’s actual services.</p>')])]:
        write(path, shell(path,title,desc,title.split(':')[0],answer,parts,trust=True))

    for file in ['mods/multiplayer/index.html','mods/index.html']:
        original = json.loads((ROOT/'scripts/longtail_sources'/(file.replace('/','_')+'.json')).read_text(encoding='utf-8'))['html']
        text = original.replace('0.4.1','0.5.3')
        text = text.replace('0.5.3<br>Updated Jul 8, 2026','0.5.3<br>Checked October 28, 2026').replace('<td>0.5.3</td><td>Jul 8, 2026</td>','<td>0.5.3</td><td>Checked Oct 28, 2026</td>')
        text = text.replace('Checked July 24, 2026','Checked October 28, 2026').replace('when checked July 24, 2026','when checked October 28, 2026')
        text = text.replace("Versions, dates and dependencies above were checked against Thunderstore's package records and packaged README files on July 24, 2026.", "Package versions, author descriptions and live dependency pages were rechecked October 28, 2026. Together requires IL2CPP 6.0.738; BonkWithFriends requires 6.0.755. No current-patch multiplayer run was completed here.")
        text = text.replace('"dateModified":"2026-07-24"','"dateModified":"2026-10-28"')
        callout = '<p class="notice"><a href="/mods/megabonk-together-vs-bonk-with-friends/">MegabonkTogether vs BonkWithFriends: choose by session needs, dependencies and reported limits</a>. This installation page keeps the setup steps; the comparison does not claim a current stability winner.</p>'
        if file=='mods/multiplayer/index.html':
            text = text.replace('<section id="install">',callout+'<section id="install">',1)
        else:
            text = text.replace('<div class="notice"><p><strong>Looking specifically for co-op?',callout+'<div class="notice"><p><strong>Looking specifically for co-op?',1)
        (ROOT/file).write_text(text,encoding='utf-8')
    # Idempotent contextual entries; protected old metadata and nav stay intact.
    for file, marker, block in [
        ('index.html', '<div class="route-grid">', '<a class="route-card" href="/guides/pokemon-games-like-megabonk/" id="pokemon-game-choice"><h3>Pokémon games like Megabonk</h3><p>Identify PokeBonk or PokéSurvivor and choose by 3D or 2D play and separate progression.</p><span class="route-link">Compare the games →</span></a>'),
        ('guides/index.html', '<section class="container" id="pokebonk-guide"', '<section class="container" id="pokemon-game-choice" style="padding:2rem 1rem"><h2>Find the Pokémon survivor from a video</h2><p><a style="color:#ff9a57;text-decoration:underline" href="/guides/pokemon-games-like-megabonk/">Compare PokeBonk, PokéSurvivor and the original Megabonk</a> before using their different controls, builds or accounts.</p></section>')]:
        f = ROOT/file
        text = f.read_text(encoding='utf-8')
        if 'id="pokemon-game-choice"' not in text:
            assert marker in text, file
            text = text.replace(marker, marker+block if marker.endswith('>') else block+marker, 1)
            f.write_text(text, encoding='utf-8')
    print('Built 2 main task pages, 2 necessary publisher pages and 2 existing mod-page patches.')


if __name__ == '__main__':
    build()
